package com.mockarena.evaluation.infrastructure;
import com.fasterxml.jackson.databind.JsonNode; import org.springframework.beans.factory.annotation.Value; import org.springframework.stereotype.Component; import org.springframework.web.client.*; import java.util.*;
@Component public class QuestionCodingSpecClient { private final RestClient client; private final String token; public QuestionCodingSpecClient(@Value("${question-service.base-url}")String base,@Value("${evaluation.workload-auth.question-coding-token:}")String token){client=RestClient.builder().baseUrl(base).build();this.token=token;} public Spec resolve(UUID id){try{Response r=client.post().uri("/internal/v1/question-versions/coding-evaluation-data").header("X-MockArena-Workload-Token",token).body(new Request(List.of(id))).retrieve().body(Response.class);if(r==null||r.entries()==null||r.entries().size()!=1)throw new RemoteDependencyException("QUESTION_SPEC_INVALID",null);Entry e=r.entries().getFirst();if(!id.equals(e.questionVersionId())||!"CODING".equals(e.questionTypeCode())||!"java-21-stdio-v1".equals(e.runtimeProfileId()))throw new RemoteDependencyException("QUESTION_SPEC_INVALID",null);return new Spec(e.questionVersionId(),e.runtimeProfileId(),e.allowedProgrammingLanguages(),e.executionLimits(),e.scoringPolicy(),e.testSpecification());}catch(RestClientException e){throw new RemoteDependencyException("QUESTION_SPEC_UNAVAILABLE",e);}} record Request(List<UUID> questionVersionIds){} record Response(List<Entry> entries){} record Entry(UUID questionVersionId,String questionTypeCode,String runtimeProfileId,JsonNode allowedProgrammingLanguages,JsonNode executionLimits,JsonNode scoringPolicy,JsonNode testSpecification){} public record Spec(UUID questionVersionId,String runtimeProfileId,JsonNode allowedProgrammingLanguages,JsonNode executionLimits,JsonNode scoringPolicy,JsonNode testSpecification){} }
